import sys

def count(text):
    lines = text.count('\n')
    # A final line with no trailing newline still counts as a line
    if text and not text.endswith('\n'):
        lines += 1
    words = len(text.split())
    chars = len(text.encode('utf-8')) if isinstance(text, str) else len(text)
    return lines, words, chars

def main():
    args = sys.argv[1:]
    show_line = False
    show_word = False
    show_char = False
    filename = None

    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-'):
            for ch in arg[1:]:
                if ch == 'l':
                    show_line = True
                elif ch == 'w':
                    show_word = True
                elif ch == 'c':
                    show_char = True
        else:
            filename = arg
        i += 1

    if not any([show_line, show_word, show_char]):
        show_line = True
        show_word = True
        show_char = True

    if filename is None or filename == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filename, 'rb') as f:
            data = f.read()

    # Count characters as bytes
    chars = len(data)
    # Decode for line/word counting
    text = data.decode('utf-8', errors='replace')
    lines = text.count('\n')
    if text and not text.endswith('\n'):
        lines += 1
    words = len(text.split())

    results = []
    if show_line:
        results.append(str(lines))
    if show_word:
        results.append(str(words))
    if show_char:
        results.append(str(chars))

    print(' '.join(results))

if __name__ == '__main__':
    main()
